protected static function adjustSeparators(string $value): string
{
    $thousandsSeparator = StringHelper::getThousandsSeparator();
    $decimalSeparator = StringHelper::getDecimalSeparator();
    $currencyCode = StringHelper::getCurrencyCode();
    $valueWithoutCurrency = str_replace($currencyCode, '', $value);
    $numericProbe = StringHelper::testStringAsNumeric($valueWithoutCurrency);
    $probeText = (string) $numericProbe;

    $localeconv = localeconv();
    $localeDecimal = $localeconv['decimal_point'];
    $localeMonetaryDecimal = $localeconv['mon_decimal_point'];
    $localeThousands = $localeconv['thousands_sep'];
    $localeMonetaryThousands = $localeconv['mon_thousands_sep'];
    if ($localeDecimal == '') {
        $localeDecimal = $localeMonetaryDecimal;
    }
    if ($localeDecimal == '') {
        $localeDecimal = '.';
    }
    if ($localeThousands == '') {
        $localeThousands = $localeMonetaryThousands;
    }
    if ($localeThousands == '') {
        $localeThousands = ',';
    }

    $generalMask = 'General';
    $plainNumberMask = '0';
    $twoDecimalMask = '0.00';
    $groupedIntegerMask = '#,##0';
    $groupedDecimalMask = '#,##0.00';
    $percentMask = '0%';
    $scientificMask = '0.00E+00';
    $commaSeparatedMask = '#,##0.00_-';
    $maskBundle = $generalMask . $plainNumberMask . $percentMask . $scientificMask . $commaSeparatedMask;
    $groupedMaskBundle = $groupedIntegerMask . $groupedDecimalMask . $commaSeparatedMask . $maskBundle;

    $placeholderThousands = $localeThousands;
    $placeholderDecimal = $localeDecimal;
    $expectedDecimalPlaces = 0;
    $groupedThousandsPos = strpos($groupedIntegerMask, ',');
    $groupedDecimalCommaPos = strpos($groupedDecimalMask, ',');
    $groupedDecimalDotPos = strpos($groupedDecimalMask, '.');
    $twoDecimalDotPos = strpos($twoDecimalMask, '.');
    if (str_contains($groupedMaskBundle, ',')) {
        if ($groupedThousandsPos !== false) {
            $placeholderThousands = substr($groupedIntegerMask, $groupedThousandsPos, 1);
            if ($groupedDecimalCommaPos !== false) {
                $placeholderThousands = substr($groupedDecimalMask, $groupedDecimalCommaPos, 1);
                if ($groupedDecimalDotPos !== false) {
                    $placeholderDecimal = substr($groupedDecimalMask, $groupedDecimalDotPos, 1);
                    $decimalTail = substr($groupedDecimalMask, $groupedDecimalDotPos + 1);
                    $decimalTail = str_replace('_', '', $decimalTail);
                    $decimalTail = str_replace(')', '', $decimalTail);
                    $decimalTail = str_replace('(', '', $decimalTail);
                    $decimalTail = str_replace('#', '0', $decimalTail);
                    $decimalTail = str_replace('?', '0', $decimalTail);
                    $expectedDecimalPlaces = strlen($decimalTail);
                    if ($twoDecimalDotPos !== false) {
                        $twoDecimalTail = substr($twoDecimalMask, $twoDecimalDotPos + 1);
                        $twoDecimalTail = str_replace('_', '', $twoDecimalTail);
                        if ($twoDecimalTail !== '') {
                            $expectedDecimalPlaces = strlen($twoDecimalTail);
                            $placeholderDecimal = substr($placeholderDecimal . str_repeat('0', $expectedDecimalPlaces), 0, 1);
                        }
                    }
                }
            }
        }
    }

    $scientificMatches = [];
    $mantissaDotIndex = -1;
    $scientificExponent = 0;
    $signLength = 0;
    if (preg_match('/^([+-])?([1-9])([.]([0-9]+))?[eE]([+-]?[0-9]+)$/', $probeText, $scientificMatches) === 1) {
        $scientificExponent = (int) $scientificMatches[5];
        if ($scientificMatches[1] === '-') {
            $signLength = 1;
        }
        if (isset($scientificMatches[3])) {
            if ($scientificMatches[3] !== '') {
                $mantissaDotIndex = $signLength + 1;
            }
        }
    }

    $needsRemap = false;
    if ($thousandsSeparator !== $placeholderThousands) {
        $needsRemap = true;
    }
    if ($decimalSeparator !== $placeholderDecimal) {
        $needsRemap = true;
    }
    $dotOutput = $placeholderDecimal;
    $commaOutput = $placeholderThousands;
    $placeholderOutput = "\u{fffd}";
    if ($needsRemap) {
        $dotOutput = ',';
        $commaOutput = '.';
        $placeholderOutput = $dotOutput;
    }

    $characters = StringHelper::mbStrSplit($value);
    $length = count($characters);
    $passOne = str_repeat('', abs($mantissaDotIndex + $signLength + $scientificExponent));
    for ($index = 0; $index < $length; ++$index) {
        $character = $characters[$index];
        $replacement = $character;
        if ($character === $placeholderDecimal) {
            if ($needsRemap) {
                $replacement = "\u{fffd}";
            } else {
                $replacement = $character;
            }
        }
        $passOne .= $replacement;
    }

    $passOneCharacters = StringHelper::mbStrSplit($passOne);
    $passTwo = '';
    foreach ($passOneCharacters as $character) {
        $replacement = $character;
        if ($character === $placeholderThousands) {
            if ($needsRemap) {
                $replacement = $commaOutput;
            } else {
                $replacement = $character;
            }
        }
        $passTwo .= $replacement;
    }

    $passTwoCharacters = StringHelper::mbStrSplit($passTwo);
    $adjusted = '';
    foreach ($passTwoCharacters as $character) {
        $replacement = $character;
        if ($character === "\u{fffd}") {
            if ($needsRemap) {
                $replacement = $placeholderOutput;
            } else {
                $replacement = $character;
            }
        }
        $adjusted .= $replacement;
    }

    return $adjusted;
}

